import{_ as e,o as t,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"外部系统集成架构","description":"按同步调用、异步消息、Webhook、回调和文件接入选择集成模式，并设计契约、身份、一致性、可靠性与安全边界。","frontmatter":{"title":"外部系统集成架构","description":"按同步调用、异步消息、Webhook、回调和文件接入选择集成模式，并设计契约、身份、一致性、可靠性与安全边界。","verified_at":"2026-08-03","source":["https://www.rfc-editor.org/rfc/rfc9110","https://www.rfc-editor.org/rfc/rfc9457","https://cloudevents.io/","https://cheatsheetseries.owasp.org/cheatsheets/Server_Side_Request_Forgery_Prevention_Cheat_Sheet.html"],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"py-agent/architecture/system-architecture/external-integration-architecture.md","filePath":"py-agent/architecture/system-architecture/external-integration-architecture.md","lastUpdated":1786083160000}'),o={name:"py-agent/architecture/system-architecture/external-integration-architecture.md"};function i(l,a,h,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="外部系统集成架构" tabindex="-1">外部系统集成架构 <a class="header-anchor" href="#外部系统集成架构" aria-label="Permalink to &quot;外部系统集成架构&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 只有接入订单、邮件、知识源、浏览器、支付或工单系统，才可能完成真实业务任务。外部系统同时也是最不稳定、最不可信且最容易产生副作用的边界：接口会超时和限流，回调可能重复乱序，文件可能携带恶意内容，模型还可能提出超出用户权限的调用。</p><p>本文讨论系统之间如何分配责任和选择交互模式。HTTP 客户端、队列、Outbox、重试和认证的具体实现位于“Agent 应用工程”；系统级安全、SLO 和故障演练位于“质量与生产”。本文负责把这些机制组织成可解释的集成架构。</p><h2 id="_1-集成边界" tabindex="-1">1. 集成边界 <a class="header-anchor" href="#_1-集成边界" aria-label="Permalink to &quot;1. 集成边界&quot;">​</a></h2><h3 id="_1-1-外部系统是什么" tabindex="-1">1.1 外部系统是什么 <a class="header-anchor" href="#_1-1-外部系统是什么" aria-label="Permalink to &quot;1.1 外部系统是什么&quot;">​</a></h3><p>外部系统不只指第三方 SaaS。只要一个能力拥有独立部署、数据、身份、版本或故障责任，即使属于同一公司，也应按外部依赖设计。Agent Runtime 不能假设订单 API、模型端点或知识源与自己处于同一事务和可用性边界。</p><h3 id="_1-2-agent-的责任" tabindex="-1">1.2 Agent 的责任 <a class="header-anchor" href="#_1-2-agent-的责任" aria-label="Permalink to &quot;1.2 Agent 的责任&quot;">​</a></h3><p>模型可以根据任务提出“查询订单”或“创建退款”候选动作，但应用负责选择允许的集成、建立可信身份、校验参数、执行调用并判断业务结果。模型说“已发送”或网页显示“成功”，都不是权威完成证据。</p><h3 id="_1-3-集成架构要决定什么" tabindex="-1">1.3 集成架构要决定什么 <a class="header-anchor" href="#_1-3-集成架构要决定什么" aria-label="Permalink to &quot;1.3 集成架构要决定什么&quot;">​</a></h3><ul><li>使用同步请求、异步消息、Webhook、回调还是文件交换；</li><li>哪一方拥有业务事实和操作状态；</li><li>身份、授权和凭据怎样传播；</li><li>超时、重复、乱序和部分成功如何处理；</li><li>外部数据进入模型与存储前经过哪些信任边界；</li><li>如何观测、对账、降级、迁移和退出供应商。</li></ul><h2 id="_2-稳定集成契约" tabindex="-1">2. 稳定集成契约 <a class="header-anchor" href="#_2-稳定集成契约" aria-label="Permalink to &quot;2. 稳定集成契约&quot;">​</a></h2><h3 id="_2-1-内部端口" tabindex="-1">2.1 内部端口 <a class="header-anchor" href="#_2-1-内部端口" aria-label="Permalink to &quot;2.1 内部端口&quot;">​</a></h3><p>业务用例依赖 <code>OrderReader</code>、<code>RefundCreator</code>、<code>DocumentSource</code> 等内部契约，适配器负责供应商 SDK、HTTP、分页、签名和字段转换。这样做不是为了隐藏所有差异，而是防止供应商类型、错误和版本直接成为业务规则。</p><h3 id="_2-2-数据映射" tabindex="-1">2.2 数据映射 <a class="header-anchor" href="#_2-2-数据映射" aria-label="Permalink to &quot;2.2 数据映射&quot;">​</a></h3><p>外部 ID、状态、金额、时区和枚举映射到内部类型，并保存原始标识以便查询和对账。两个系统都叫 <code>completed</code>，含义可能分别是“请求已接收”和“资金已结算”，不能按字段名推断语义等价。</p><h3 id="_2-3-错误模型" tabindex="-1">2.3 错误模型 <a class="header-anchor" href="#_2-3-错误模型" aria-label="Permalink to &quot;2.3 错误模型&quot;">​</a></h3><p>稳定地区分无效输入、未认证、未授权、资源不存在、冲突、限流、超时、不可用和未知结果。RFC 9457 的 Problem Details 可以规范 HTTP 错误载体，但应用仍需把外部错误转换成自己的重试、用户提示和任务状态。</p><h3 id="_2-4-操作身份" tabindex="-1">2.4 操作身份 <a class="header-anchor" href="#_2-4-操作身份" aria-label="Permalink to &quot;2.4 操作身份&quot;">​</a></h3><p>所有可能产生副作用的调用都使用稳定 <code>operation_id</code> 或幂等键，并保存外部资源 ID、请求摘要和结果。网络超时只说明客户端没有收到确定响应，不能证明服务端没有执行。</p><h2 id="_3-交互模式" tabindex="-1">3. 交互模式 <a class="header-anchor" href="#_3-交互模式" aria-label="Permalink to &quot;3. 交互模式&quot;">​</a></h2><h3 id="_3-1-同步请求与响应" tabindex="-1">3.1 同步请求与响应 <a class="header-anchor" href="#_3-1-同步请求与响应" aria-label="Permalink to &quot;3.1 同步请求与响应&quot;">​</a></h3><p>调用方等待结果，适合低延迟查询、快速校验和能够在当前 Deadline 内完成的幂等动作。同步链越长，尾延迟和级联故障越明显；长任务不应长期占用 API 连接假装仍是同步操作。</p><h3 id="_3-2-异步命令与事件" tabindex="-1">3.2 异步命令与事件 <a class="header-anchor" href="#_3-2-异步命令与事件" aria-label="Permalink to &quot;3.2 异步命令与事件&quot;">​</a></h3><p>调用方提交工作或发布已发生事实，消费者稍后处理。命令表达“请执行”，事件表达“已经发生”，两者拥有不同的权限、重试和幂等语义。队列提供交付和背压，不自动提供业务事务一致性。</p><h3 id="_3-3-webhook" tabindex="-1">3.3 Webhook <a class="header-anchor" href="#_3-3-webhook" aria-label="Permalink to &quot;3.3 Webhook&quot;">​</a></h3><p>外部系统主动通知本系统。Webhook 可能重复、延迟、乱序，也可能在本系统响应超时后重发。接收端验证签名、时间、事件 ID 和版本，快速持久化后返回，再由 Worker 幂等处理。</p><h3 id="_3-4-回调" tabindex="-1">3.4 回调 <a class="header-anchor" href="#_3-4-回调" aria-label="Permalink to &quot;3.4 回调&quot;">​</a></h3><p>本系统向租户或合作方提供的 URL 发送结果。回调目标是用户控制的网络输入，需要限制协议、主机、解析后的 IP、重定向、端口、响应大小和 Deadline，并通过受控网络出口防止 SSRF。</p><h3 id="_3-5-文件与内容交换" tabindex="-1">3.5 文件与内容交换 <a class="header-anchor" href="#_3-5-文件与内容交换" aria-label="Permalink to &quot;3.5 文件与内容交换&quot;">​</a></h3><p>批量文件、邮件、网页和文档适合数据量大、接口缺失或需要异步处理的场景。接入层验证真实类型、大小、数量、哈希、来源和许可；解析在隔离环境完成。文件中的文字是不可信数据，不能改变 Agent 的权限或系统指令。</p><h2 id="_4-模式选择" tabindex="-1">4. 模式选择 <a class="header-anchor" href="#_4-模式选择" aria-label="Permalink to &quot;4. 模式选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>约束</th><th>首选模式</th><th>主要代价</th></tr></thead><tbody><tr><td>用户当前请求必须立即得到小结果</td><td>同步请求</td><td>受共同 Deadline 和级联故障影响</td></tr><tr><td>执行时间长、可排队或需要恢复</td><td>异步命令 + 状态查询</td><td>需要任务状态、幂等和通知</td></tr><tr><td>外部系统掌握状态变化</td><td>Webhook + 主动对账</td><td>重复、乱序和签名管理</td></tr><tr><td>需要把结果推送给租户系统</td><td>受控回调</td><td>SSRF、重试和租户端故障</td></tr><tr><td>大批量或无实时接口</td><td>文件交换</td><td>扫描、解析、延迟和版本治理</td></tr><tr><td>必须跨事务可靠发布事实</td><td>本地事务 + Outbox + 事件</td><td>最终一致和对账</td></tr></tbody></table><p>同一业务可以组合模式。例如创建研究任务使用同步 API 返回 <code>task_id</code>，后台异步执行，完成后发送 Webhook；用户仍可用状态查询作为 Webhook 丢失时的恢复路径。</p><h2 id="_5-身份、授权与凭据" tabindex="-1">5. 身份、授权与凭据 <a class="header-anchor" href="#_5-身份、授权与凭据" aria-label="Permalink to &quot;5. 身份、授权与凭据&quot;">​</a></h2><h3 id="_5-1-平台身份" tabindex="-1">5.1 平台身份 <a class="header-anchor" href="#_5-1-平台身份" aria-label="Permalink to &quot;5.1 平台身份&quot;">​</a></h3><p>平台统一账户适合共享只读能力，但每次调用仍记录内部租户、主体和用途。外部系统只看到平台身份时，内部审计必须能够回答是谁触发了哪个动作。</p><h3 id="_5-2-用户委托" tabindex="-1">5.2 用户委托 <a class="header-anchor" href="#_5-2-用户委托" aria-label="Permalink to &quot;5.2 用户委托&quot;">​</a></h3><p>需要代表用户访问日历、邮箱等资源时，使用最小 Scope、明确令牌受众（Audience）和短期访问令牌。刷新令牌由 Secret 系统保存，不进入 Prompt、State、Checkpoint 或普通日志；用户撤销后停止新调用。</p><h3 id="_5-3-服务到服务" tabindex="-1">5.3 服务到服务 <a class="header-anchor" href="#_5-3-服务到服务" aria-label="Permalink to &quot;5.3 服务到服务&quot;">​</a></h3><p>Worker、工具网关和外部服务使用独立服务身份，并把业务 Principal 作为受验证的委托上下文传播。服务身份拥有调用通道不代表它可以替任意用户访问任意资源。</p><h3 id="_5-4-租户自带凭据" tabindex="-1">5.4 租户自带凭据 <a class="header-anchor" href="#_5-4-租户自带凭据" aria-label="Permalink to &quot;5.4 租户自带凭据&quot;">​</a></h3><p>租户自带凭据时，应按租户加密、轮换和审计，并把连接测试与真实调用分开。支持人员默认不能读取明文凭据，错误日志不得记录完整 Authorization Header、Cookie 或签名材料。</p><h2 id="_6-可靠性边界" tabindex="-1">6. 可靠性边界 <a class="header-anchor" href="#_6-可靠性边界" aria-label="Permalink to &quot;6. 可靠性边界&quot;">​</a></h2><h3 id="_6-1-deadline-与取消" tabindex="-1">6.1 Deadline 与取消 <a class="header-anchor" href="#_6-1-deadline-与取消" aria-label="Permalink to &quot;6.1 Deadline 与取消&quot;">​</a></h3><p>上游总 Deadline 向下游传递剩余预算，连接、读取和完整调用分别设限。取消要停止尚未需要的模型和网络请求；已经提交的不可取消动作进入状态查询或补偿流程。</p><h3 id="_6-2-有限重试" tabindex="-1">6.2 有限重试 <a class="header-anchor" href="#_6-2-有限重试" aria-label="Permalink to &quot;6.2 有限重试&quot;">​</a></h3><p>只对已识别的瞬态错误和幂等操作重试，遵守 <code>Retry-After</code>，使用退避与随机抖动（Jitter）。API、SDK、任务框架和代理若各自独立重试，会形成不可预测的流量放大。</p><h3 id="_6-3-熔断与隔舱" tabindex="-1">6.3 熔断与隔舱 <a class="header-anchor" href="#_6-3-熔断与隔舱" aria-label="Permalink to &quot;6.3 熔断与隔舱&quot;">​</a></h3><p>持续失败时暂停对依赖的新调用，使用半开探测恢复。不同外部系统使用独立连接池、并发和队列，使一个慢供应商不能耗尽全部 Agent Worker。</p><h3 id="_6-4-未知结果" tabindex="-1">6.4 未知结果 <a class="header-anchor" href="#_6-4-未知结果" aria-label="Permalink to &quot;6.4 未知结果&quot;">​</a></h3><p>写操作超时后，系统状态不是简单的“失败”，而是“结果未知”。优先使用 <code>operation_id</code> 查询外部权威状态；无法确认时转人工或进入对账，不能直接重试可能重复扣款、发送或删除的动作。</p><h3 id="_6-5-降级" tabindex="-1">6.5 降级 <a class="header-anchor" href="#_6-5-降级" aria-label="Permalink to &quot;6.5 降级&quot;">​</a></h3><p>降级由业务语义决定：只读缓存、返回数据水位、转后台、切换人工、暂停写操作或安全失败。备用供应商仍需满足数据地域、身份、功能和质量门槛，不能只因为端点可连接就自动切换。</p><h2 id="_7-一致性与对账" tabindex="-1">7. 一致性与对账 <a class="header-anchor" href="#_7-一致性与对账" aria-label="Permalink to &quot;7. 一致性与对账&quot;">​</a></h2><h3 id="_7-1-outbox-与-inbox" tabindex="-1">7.1 Outbox 与 Inbox <a class="header-anchor" href="#_7-1-outbox-与-inbox" aria-label="Permalink to &quot;7.1 Outbox 与 Inbox&quot;">​</a></h3><p>本地业务事实和待发布事件在同一事务写入 Outbox，发布器至少一次发送；消费者以事件 ID 写 Inbox 或幂等记录。该模式解决提交后可恢复发布，不会回滚已经在另一个系统完成的动作。</p><h3 id="_7-2-顺序与版本" tabindex="-1">7.2 顺序与版本 <a class="header-anchor" href="#_7-2-顺序与版本" aria-label="Permalink to &quot;7.2 顺序与版本&quot;">​</a></h3><p>消息和 Webhook 可能乱序。资源版本、事件序列或业务时间决定是否接受更新，而不是网络到达顺序。发现版本缺口时主动读取权威 API 或暂停处理，不能用较晚到达的旧事件覆盖新状态。</p><h3 id="_7-3-定期对账" tabindex="-1">7.3 定期对账 <a class="header-anchor" href="#_7-3-定期对账" aria-label="Permalink to &quot;7.3 定期对账&quot;">​</a></h3><p>对高价值或可能结果未知的动作，定期比较本地操作记录与外部权威状态。对账输出差异、影响、自动修复条件和人工队列；它是正常架构能力，不只是事故后的临时脚本。</p><h2 id="_8-不可信内容边界" tabindex="-1">8. 不可信内容边界 <a class="header-anchor" href="#_8-不可信内容边界" aria-label="Permalink to &quot;8. 不可信内容边界&quot;">​</a></h2><p>外部 API 字段、网页、邮件、文档和工具返回都可能包含 Prompt Injection 或敏感数据。接入层将它们标记为数据，Context Builder 只选择任务必需内容，Tool Policy 不接受内容中的提权指令。</p><p>文件解析器、浏览器和媒体处理在受限进程、容器或 VM 中运行，限制网络、文件、CPU、内存和时间。外部 URL 下载经过 SSRF 防护；上传、下载和回调是独立的数据出口，需要权限与审计。</p><h2 id="_9-参考架构-退款外部集成" tabindex="-1">9. 参考架构：退款外部集成 <a class="header-anchor" href="#_9-参考架构-退款外部集成" aria-label="Permalink to &quot;9. 参考架构：退款外部集成&quot;">​</a></h2><h3 id="_9-1-交互选择" tabindex="-1">9.1 交互选择 <a class="header-anchor" href="#_9-1-交互选择" aria-label="Permalink to &quot;9.1 交互选择&quot;">​</a></h3><p>假设售后 Agent 查询订单、创建退款并接收支付系统状态更新：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent Use Case</span></span>
<span class="line"><span>  -&gt; OrderReader ----------&gt; 订单 API（同步只读）</span></span>
<span class="line"><span>  -&gt; RefundCommand --------&gt; 本地退款任务 + Outbox</span></span>
<span class="line"><span>  -&gt; Refund Worker --------&gt; 支付 API（幂等写入）</span></span>
<span class="line"><span>  &lt;- Payment Webhook ------- 支付状态事件</span></span>
<span class="line"><span>  -&gt; Reconciliation Job ---&gt; 支付查询 API（定期对账）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>订单查询位于用户请求 Deadline 内；退款先形成可恢复的本地任务，再由 Worker 使用稳定操作 ID 执行；Webhook 加速状态更新；主动查询保证即使 Webhook 丢失也能收敛。</p><h3 id="_9-2-状态模型" tabindex="-1">9.2 状态模型 <a class="header-anchor" href="#_9-2-状态模型" aria-label="Permalink to &quot;9.2 状态模型&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proposed -&gt; awaiting_approval -&gt; queued -&gt; submitting</span></span>
<span class="line"><span>                                      -&gt; succeeded</span></span>
<span class="line"><span>                                      -&gt; rejected</span></span>
<span class="line"><span>                                      -&gt; outcome_unknown -&gt; reconciling</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>outcome_unknown</code> 不是普通失败。只有支付系统按操作 ID 证明未创建，系统才允许安全重试；证明已创建则补写本地终态；仍无法确定则交给人工处理。</p><h3 id="_9-3-完成证据" tabindex="-1">9.3 完成证据 <a class="header-anchor" href="#_9-3-完成证据" aria-label="Permalink to &quot;9.3 完成证据&quot;">​</a></h3><p>最终结果保存本地退款 ID、外部退款 ID、操作 ID、金额、状态、外部版本和更新时间。模型输出、HTTP 200 或 Webhook 单次到达都不是独立完成 Oracle，业务终态由支付权威状态和本地不变量共同确认。</p><h2 id="_10-可观测与运营" tabindex="-1">10. 可观测与运营 <a class="header-anchor" href="#_10-可观测与运营" aria-label="Permalink to &quot;10. 可观测与运营&quot;">​</a></h2><p>每个集成记录调用类型、外部系统、操作 ID、状态、延迟、重试、限流、熔断、队列积压和外部版本，并关联 Task、Run 和 Trace。正文和凭据按最小化策略采集。</p><p>运营工具应支持连接测试、凭据状态、最近成功、失败分类、待对账记录、Webhook 重放和受控人工处理。重放必须复用原事件或操作身份，不能把同一副作用伪装成新请求。</p><h2 id="_11-验收与复查" tabindex="-1">11. 验收与复查 <a class="header-anchor" href="#_11-验收与复查" aria-label="Permalink to &quot;11. 验收与复查&quot;">​</a></h2><h3 id="_11-1-契约测试" tabindex="-1">11.1 契约测试 <a class="header-anchor" href="#_11-1-契约测试" aria-label="Permalink to &quot;11.1 契约测试&quot;">​</a></h3><p>验证请求、响应、分页、错误、版本和字段语义，使用供应商沙箱或可控替身覆盖限流、超时、重复和未知枚举。契约测试证明适配器理解接口，不证明完整业务流程成功。</p><h3 id="_11-2-故障测试" tabindex="-1">11.2 故障测试 <a class="header-anchor" href="#_11-2-故障测试" aria-label="Permalink to &quot;11.2 故障测试&quot;">​</a></h3><p>至少验证响应丢失但服务端成功、Webhook 重复乱序、凭据撤销、回调重定向到内网、文件解析超限、队列重复投递和供应商长期不可用。检查最终业务状态、重复副作用、积压和降级是否符合设计。</p><h3 id="_11-3-复查条件" tabindex="-1">11.3 复查条件 <a class="header-anchor" href="#_11-3-复查条件" aria-label="Permalink to &quot;11.3 复查条件&quot;">​</a></h3><p>外部 API 版本、数据政策、身份模式、调用量、SLO、错误分布或业务副作用变化时复查集成模式。同步链频繁超时、对账差异增加或运营人员长期手工修复，说明当前边界已经不匹配真实系统。</p><p>外部集成的核心不是成功发出请求，而是把独立系统之间的不确定性变成明确状态：谁拥有事实、调用是否发生、失败能否重试、结果如何对账，以及不可信内容能否影响权限。只有这些问题都有可验证答案，Agent 才真正具备执行业务动作的能力。</p>`,85)])])}const b=e(o,[["render",i]]);export{u as __pageData,b as default};
